def solve():
    memo_f = {}
    memo_g = {}

    def f(boards):
        boards = tuple(sorted([b for b in boards if b > 0]))
        if not boards:
            return 0
        if boards in memo_f:
            return memo_f[boards]

        res = -1
        # Alice's turn. She can choose any board and any tile position.
        for i, b in enumerate(boards):
            for pos in range(1, b):
                new_boards = list(boards)
                new_boards.pop(i)
                if pos - 1 > 0:
                    new_boards.append(pos - 1)
                if b - pos - 1 > 0:
                    new_boards.append(b - pos - 1)

                res = max(res, g(tuple(new_boards)))

        memo_f[boards] = res
        return res

    def g(boards):
        boards = tuple(sorted([b for b in boards if b > 0]))
        if not boards:
            return 0
        if boards in memo_g:
            return memo_g[boards]

        # If no move is possible, the number of uncovered squares is the sum of board sizes.
        can_move = False
        for b in boards:
            if b >= 2:
                can_move = True
                break

        if not can_move:
            return sum(boards)

        res = float('inf')
        # Bob's turn. He wants to minimize the result.
        for i, b in enumerate(boards):
            for pos in range(1, b):
                new_boards = list(boards)
                new_boards.pop(i)
                if pos - 1 > 0:
                    new_boards.append(pos - 1)
                if b - pos - 1 > 0:
                    new_boards.append(b - pos - 1)

                res = min(res, f(tuple(new_boards)))

        memo_g[boards] = res
        return res

    for n in range(1, 15):
        memo_f.clear()
        memo_g.clear()
        print(f"n={n}: {f((n,))}")

solve()

